<?php
/** Montagem fiscal defensiva da DPS 1.01, compatível com nfse-php v1.21. */
function nfseDig($v): ?string { $v=preg_replace('/\D/','',(string)($v??'')); return $v===''?null:$v; }
function nfseTxt($v): ?string { $v=trim((string)($v??'')); return $v===''?null:$v; }
// Inscrição Municipal: varia por prefeitura e algumas usam dígito verificador alfanumérico (ex.:
// Belo Horizonte termina em "X", como no CPF). nfseDig (só números) cortaria essa letra e quebraria
// a IM; nfseTxt manteria pontuação digitada (pontos/barra/traço) que o cadastro nacional (CNC) não
// reconhece. Mantém letras e números, remove só a pontuação.
function nfseAlfanum($v): ?string { $v=strtoupper(preg_replace('/[^A-Za-z0-9]/','',(string)($v??''))); return $v===''?null:$v; }
function nfseNum($v): ?float { return $v===null||$v===''?null:round((float)$v,2); }
function nfseLimpa(array $a): array { foreach($a as $k=>$v){if(is_array($v)){ $v=nfseLimpa($v); if($v===[])unset($a[$k]);else$a[$k]=$v;}elseif($v===null||$v==='')unset($a[$k]);}return $a; }
function nfseItemCatalogoFiscal(string $grupo,string $codigo): ?array { static $catalogo=null;if($catalogo===null){$catalogo=cacheJsonArquivo(__DIR__.'/nfse-ibs-catalogos.json');}foreach($catalogo[$grupo]??[] as $item)if((string)($item['codigo']??'')===$codigo)return $item;return null; }
function nfseRegEsp(?string $v): int { return match($v){null,'','mei','me_epp_simples_nacional'=>0,'cooperativa'=>1,'estimativa'=>2,'microempresa_municipal'=>3,'notario_registrador'=>4,'profissional_autonomo'=>5,'sociedade_profissionais'=>6,default=>throw new InvalidArgumentException('Regime especial de tributação inválido.')}; }
function nfseOpSimples(array $e,array $n): ?int { $v=$e['nfse_opcao_simples_nacional']??$e['opcao_simples_nacional']??$n['opcao_simples_nacional']??null; if($v!==null&&in_array((int)$v,[1,2,3],true))return(int)$v; return match($n['regime_especial_tributacao']??null){'mei'=>2,'me_epp_simples_nacional'=>3,default=>null}; }
function nfseTribIss(?string $v): int { return match($v){null,'','operacao_tributavel'=>1,'imune'=>2,'exportacao'=>3,'nao_incidencia'=>4,'isenta'=>throw new InvalidArgumentException('O DPS 1.01 não possui código autônomo para isenção; revise imunidade/não incidência.'),default=>throw new InvalidArgumentException('Tributação ISSQN inválida.')}; }
function nfseEnd(array $p,bool $ext,array &$err,string $quem): ?array {
 $l=nfseTxt($p['logradouro']??null);$num=nfseTxt($p['numero']??null);$b=nfseTxt($p['bairro']??null);
 if($ext){$pais=nfseDig($p['codigo_pais']??$p['pais_codigo']??null);$cid=nfseTxt($p['cidade_exterior']??$p['municipio']??null);if(!$pais||!$cid||!$l||!$num){$err[]="Endereço exterior do $quem exige código BACEN do país, cidade, logradouro e número.";return null;}return nfseLimpa(['endExt'=>['cPais'=>$pais,'cEndPost'=>nfseTxt($p['cep']??null),'xCidade'=>$cid,'xEstProvReg'=>nfseTxt($p['estado_provincia_regiao']??$p['uf']??null)],'xLgr'=>$l,'nro'=>$num,'xCpl'=>nfseTxt($p['complemento']??null),'xBairro'=>$b]);}
 $mun=nfseDig($p['codigo_ibge_municipio']??null);$cep=nfseDig($p['cep']??null);if(strlen((string)$mun)!==7||strlen((string)$cep)!==8||!$l||!$num||!$b){$err[]="Endereço nacional do $quem exige código IBGE, CEP, logradouro, número e bairro.";return null;}return nfseLimpa(['endNac'=>['cMun'=>$mun,'CEP'=>$cep],'xLgr'=>$l,'nro'=>$num,'xCpl'=>nfseTxt($p['complemento']??null),'xBairro'=>$b]);
}
function nfseToma(array $c,array $n,array &$err): array { $ext=($n['tomador_local']??'')==='exterior';$t=['xNome'=>nfseTxt($c['nome_razao_social']??null),'end'=>nfseEnd($c,$ext,$err,'tomador'),'fone'=>nfseDig($n['tomador_telefone']??$c['telefone']??null),'email'=>nfseTxt($c['email']??null)];if($ext){$nif=nfseTxt($c['nif']??null);$mot=$c['motivo_nao_nif']??$c['codigo_nao_nif']??null;if($nif)$t['NIF']=$nif;elseif(in_array((int)$mot,[1,2],true))$t['cNaoNIF']=(int)$mot;else$err[]='Tomador exterior exige NIF ou motivo de ausência (1 ou 2).';}else{$doc=nfseDig($c['cnpj_cpf']??null);if(!in_array(strlen((string)$doc),[11,14],true))$err[]='Tomador nacional exige CPF/CNPJ válido.';else$t[strlen($doc)===11?'CPF':'CNPJ']=$doc;$t['IM']=nfseAlfanum($n['tomador_inscricao_municipal']??$c['inscricao_municipal']??null);}if(!$t['xNome'])$err[]='Informe o nome do tomador.';return nfseLimpa($t); }
function nfseInterm(array $n,array &$err): ?array {if((int)($n['intermediario_incluido']??0)!==1)return null;$d=nfseDig($n['intermediario_cpf_cnpj']??null);$nome=nfseTxt($n['intermediario_nome']??null);if(!in_array(strlen((string)$d),[11,14],true)||!$nome){$err[]='Intermediário exige CPF/CNPJ válido e nome.';return null;}return [strlen($d)===11?'CPF':'CNPJ'=>$d,'xNome'=>$nome];}
function nfseIbs(array $n,string $comp,int $op,array &$err): ?array {$f=['finNFSe'=>nfseTxt($n['ibscbs_finalidade']??null),'indFinal'=>($n['ibscbs_ind_final']??'')===''?null:(int)$n['ibscbs_ind_final'],'cIndOp'=>nfseDig($n['ibscbs_codigo_indicador_operacao']??null),'indDest'=>($n['ibscbs_ind_destinatario']??'')===''?null:(int)$n['ibscbs_ind_destinatario'],'CST'=>nfseDig($n['ibscbs_cst']??null),'cClassTrib'=>nfseDig($n['ibscbs_classificacao_tributaria']??null)];$alg=count(array_filter($f,fn($v)=>$v!==null))>0;$obr=$op===1&&$comp>='2026-08-03';if(!$alg&&!$obr)return null;$falt=[];foreach(['finNFSe','cIndOp','indDest','CST','cClassTrib']as$k)if($f[$k]===null)$falt[]=$k;if($falt){$err[]='Complete IBS/CBS: '.implode(', ',$falt).'.';return null;}if(!preg_match('/^\d{6}$/',$f['cIndOp']))$err[]='cIndOp IBS/CBS deve ter 6 dígitos.';if(!preg_match('/^\d{3}$/',$f['CST']))$err[]='CST IBS/CBS deve ter 3 dígitos.';if(!preg_match('/^\d{6}$/',$f['cClassTrib'])||!str_starts_with($f['cClassTrib'],$f['CST']))$err[]='cClassTrib deve ter 6 dígitos e começar pelo CST.';if(!in_array($f['indDest'],[0,1],true))$err[]='indDest deve ser 0 ou 1.';$cind=nfseItemCatalogoFiscal('cindop',(string)$f['cIndOp']);$cclass=nfseItemCatalogoFiscal('cclass',(string)$f['cClassTrib']);if($cind===null)$err[]='cIndOp não consta na tabela oficial vigente da NFS-e.';if($cclass===null)$err[]='cClassTrib não consta como vigente e permitido para NFS-e.';elseif((string)($cclass['cst']??'')!==(string)$f['CST'])$err[]='CST não corresponde ao cClassTrib selecionado.';return nfseLimpa(['finNFSe'=>$f['finNFSe'],'indFinal'=>$f['indFinal'],'cIndOp'=>$f['cIndOp'],'indDest'=>$f['indDest'],'valores'=>['trib'=>['gIBSCBS'=>['CST'=>$f['CST'],'cClassTrib'=>$f['cClassTrib']]]]]);}
function nfseMontarDps(array $nota,array $e,array $c,array $itens,?array $n=null): array {$n??=[];$err=[];$cnpj=nfseDig($e['cnpj']??null);$mun=nfseDig($e['codigo_ibge_municipio']??null);if(strlen((string)$cnpj)!==14)$err[]='Empresa exige CNPJ de 14 dígitos.';if(strlen((string)$mun)!==7)$err[]='Empresa exige código IBGE de 7 dígitos.';if(!nfseAlfanum($e['inscricao_municipal']??null))$err[]='Empresa exige Inscrição Municipal cadastrada.';$serie=nfseTxt($n['serie_dps']??null)??'1';$num=nfseTxt($n['numero_dps']??null)??(string)($nota['numero_interno']??'');$comp=(string)($n['data_competencia']??$nota['data_emissao']??'');$op=nfseOpSimples($e,$n);if($op===null){$err[]='Informe explicitamente a opção NFS-e pelo Simples (1 não optante, 2 MEI, 3 ME/EPP); o CRT não é inferido.';$op=1;}$regAp=$e['nfse_regime_apuracao_sn']??$e['regime_apuracao_sn']??$n['regime_apuracao_sn']??null;if($op===3&&!in_array((int)$regAp,[1,2,3],true))$err[]='ME/EPP exige regime de apuração NFS-e 1, 2 ou 3.';$ctn=nfseDig($n['codigo_tributacao_nacional']??$itens[0]['codigo_servico_municipal']??null);$ctm=nfseDig($n['codigo_tributacao_municipal']??null);$nbs=nfseDig($n['item_nbs']??null);$loc=nfseDig($n['municipio_prestacao']??null)??$mun;if(strlen((string)$ctn)!==6)$err[]='Código de tributação nacional deve ter 6 dígitos.';if(strlen((string)$loc)!==7)$err[]='Município da prestação deve ser código IBGE de 7 dígitos.';$bruto=round(array_sum(array_map(fn($i)=>(float)($i['valor_total']??0),$itens)),2);if($bruto<=0)$bruto=round((float)($nota['valor_total']??0)+(float)($n['desconto_incondicionado']??0)+(float)($n['desconto_condicionado']??0),2);if($bruto<=0)$err[]='Valor bruto deve ser positivo.';$di=nfseNum($n['desconto_incondicionado']??null);$dc=nfseNum($n['desconto_condicionado']??null);if(($di??0)+($dc??0)>=$bruto)$err[]='Soma dos descontos deve ser menor que o valor bruto.';$ret=($n['issqn_retido']??'nao')==='sim';$tp=$ret?(($n['issqn_retido_por']??'tomador')==='intermediario'?3:2):1;if($tp===3&&(int)($n['intermediario_incluido']??0)!==1)$err[]='Retenção pelo intermediário exige sua identificação.';$tribIss=$e['nfse_tributacao_issqn']??$n['tributacao_issqn']??null;$tm=['tribISSQN'=>nfseTribIss($tribIss),'tpRetISSQN'=>$tp];$naoTrib=($n['imune_exportacao_nao_incidencia']??'nao')==='sim';$tipoNaoTrib=in_array(($tribIss??''),['imune','exportacao','nao_incidencia'],true);if($naoTrib!==$tipoNaoTrib)$err[]='A indicação de imunidade/exportação/não incidência deve ser coerente com a tributação do ISSQN selecionada.';if(($n['exigibilidade_issqn_suspensa']??'nao')==='sim'){if(!in_array((int)($n['tipo_suspensao_issqn']??0),[1,2],true)||!nfseTxt($n['numero_processo_suspensao']??null))$err[]='Suspensão exige tipo e número de processo.';else$tm['exigSusp']=['tpSusp'=>(int)$n['tipo_suspensao_issqn'],'nProcesso'=>nfseTxt($n['numero_processo_suspensao'])];}if(($n['beneficio_municipal']??'nao')==='sim'){if(!$cod=nfseTxt($n['codigo_beneficio_municipal']??null))$err[]='Benefício municipal exige código.';else$tm['BM']=['nBM'=>$cod];}$tr=['tribMun'=>$tm];$tipo=match($n['tipo_retencao_pis_cofins_csll']??null){null,''=>null,'nenhuma'=>2,'lei_10833','outras'=>1,default=>ctype_digit((string)$n['tipo_retencao_pis_cofins_csll'])?(int)$n['tipo_retencao_pis_cofins_csll']:null};$tf=nfseLimpa(['piscofins'=>['CST'=>nfseDig($n['situacao_tributaria_pis_cofins']??null),'tpRetPisCofins'=>$tipo],'vRetIRRF'=>nfseNum($n['irrf']??null),'vRetCSLL'=>nfseNum($n['contribuicoes_sociais_retidas']??null),'vRetCP'=>nfseNum($n['contribuicao_previdenciaria_retida']??null)]);if($tf)$tr['tribFed']=$tf;$tribValFed=nfseNum($n['tributos_federal_valor']??null);$tribValEst=nfseNum($n['tributos_estadual_valor']??null);$tribValMun=nfseNum($n['tributos_municipal_valor']??null);$tribPctFed=nfseNum($n['tributos_federal_percentual']??null);$tribPctEst=nfseNum($n['tributos_estadual_percentual']??null);$tribPctMun=nfseNum($n['tributos_municipal_percentual']??null);if(($n['tributos_modo']??'percentuais')==='valores'){if($tribValFed===null&&$tribValEst===null&&$tribValMun===null)$tr['totTrib']=['indTotTrib'=>0];else$tr['totTrib']=['vTotTrib'=>['vTotTribFed'=>$tribValFed??0.0,'vTotTribEst'=>$tribValEst??0.0,'vTotTribMun'=>$tribValMun??0.0]];}else{if($tribPctFed===null&&$tribPctEst===null&&$tribPctMun===null)$tr['totTrib']=['indTotTrib'=>0];else$tr['totTrib']=['pTotTrib'=>['pTotTribFed'=>$tribPctFed??0.0,'pTotTribEst'=>$tribPctEst??0.0,'pTotTribMun'=>$tribPctMun??0.0]];}$ibs=nfseIbs($n,$comp,$op,$err);if($ibs&&strlen((string)$nbs)!==9)$err[]='NBS é obrigatório com IBS/CBS e deve ter 9 dígitos.';$id=class_exists(\Nfse\Support\IdGenerator::class)&&strlen((string)$cnpj)===14&&strlen((string)$mun)===7?\Nfse\Support\IdGenerator::generateDpsId(cpfCnpj:$cnpj,codIbge:$mun,serieDps:$serie,numDps:$num):'DPSINVALIDA';if($id==='DPSINVALIDA')$err[]='Não foi possível gerar o Id da DPS.';$desc=nfseTxt($n['descricao_servico']??null)??implode('; ',array_map(fn($i)=>(string)($i['descricao']??''),$itens));$inf=nfseTxt($n['informacoes_complementares']??null);if($ped=nfseTxt($n['numero_pedido_b2b']??null))$inf=trim(($inf?$inf.' | ':'').'Pedido B2B: '.$ped);$dados=['@attributes'=>['versao'=>'1.01'],'infDPS'=>nfseLimpa(['@attributes'=>['Id'=>$id],'tpAmb'=>($nota['ambiente']??'')==='producao'?1:2,'dhEmi'=>(new DateTimeImmutable('now',new DateTimeZone('America/Sao_Paulo')))->format('c'),'verAplic'=>'AccountContab-1.1','serie'=>$serie,'nDPS'=>$num,'dCompet'=>$comp,'tpEmit'=>1,'cLocEmi'=>$mun,'prest'=>['CNPJ'=>$cnpj,'IM'=>nfseAlfanum($e['inscricao_municipal']??null),'regTrib'=>nfseLimpa(['opSimpNac'=>$op,'regApTribSN'=>$op===3?(int)$regAp:null,'regEspTrib'=>nfseRegEsp($e['nfse_regime_especial_tributacao']??$n['regime_especial_tributacao']??null)])],'toma'=>nfseToma($c,$n,$err),'interm'=>nfseInterm($n,$err),'serv'=>['locPrest'=>['cLocPrestacao'=>$loc],'cServ'=>nfseLimpa(['cTribNac'=>$ctn,'cTribMun'=>$ctm,'xDescServ'=>$desc,'cNBS'=>$nbs,'cIntContrib'=>nfseTxt($n['codigo_interno_contribuinte']??null)]),'infoCompl'=>nfseLim